 public static string Activate(InputLanguage language){object server=null;try{server=Activator.CreateInstance(Type.GetTypeFromCLSID(clsid));var profiles=(Profiles)server;Guid cat=category,tip,profile;ushort langid=(ushort)language.Culture.LCID;int hr=profiles.GetDefaultLanguageProfile(langid,ref cat,out tip,out profile);if(hr<0)return "error:default-0x"+unchecked((uint)hr).ToString("X8");bool inputProcessor=tip!=Guid.Empty&&profile!=Guid.Empty;uint type=inputProcessor?1u:2u;Guid callTip=inputProcessor?tip:Guid.Empty,callProfile=inputProcessor?profile:Guid.Empty;IntPtr hkl=inputProcessor?IntPtr.Zero:language.Handle;var manager=(Manager)server;hr=manager.ActivateProfile(type,langid,ref callTip,ref callProfile,hkl,0x30000000u|4u);if(hr==0&&inputProcessor)hr=profiles.ActivateLanguageProfile(ref callTip,langid,ref callProfile);return hr==0?"ok":"error:activate-0x"+unchecked((uint)hr).ToString("X8");}catch(Exception ex){var com=ex as COMException;return com==null?"error:"+ex.GetType().Name:"error:com-0x"+unchecked((uint)com.ErrorCode).ToString("X8");}finally{if(server!=null){try{Marshal.FinalReleaseComObject(server);}catch{}}}}
