class ProbeBox:TextBox {public static int horizontal,vertical;public int middleDown,middleUp,compositions;protected override void WndProc(ref Message m){if(m.Msg==0x10F)compositions++;if(m.Msg==0x20A)vertical+=(short)(((long)m.WParam>>16)&65535);if(m.Msg==0x20E)horizontal+=(short)(((long)m.WParam>>16)&65535);if(m.Msg==0x207)middleDown++;if(m.Msg==0x208)middleUp++;base.WndProc(ref m);}}
class ProbeForm:Form {public static int media;protected override void WndProc(ref Message m){if(m.Msg==0x319){media=(int)(((long)m.LParam>>16)&0xFFF);m.Result=new IntPtr(1);return;}if(m.Msg==0x20E)ProbeBox.horizontal+=(short)(((long)m.WParam>>16)&65535);base.WndProc(ref m);}}
class InputTarget {
 [DllImport("user32.dll")]static extern void keybd_event(byte vk,byte scan,uint flags,UIntPtr extra);
 static void Tap(byte vk){keybd_event(vk,0,0,UIntPtr.Zero);keybd_event(vk,0,2,UIntPtr.Zero);}
