 [DllImport("user32.dll")]static extern short GetAsyncKeyState(int k);
 [STAThread]static void Main(string[] args){if(Array.IndexOf(args,"--list-languages")>=0){foreach(InputLanguage item in InputLanguage.InstalledInputLanguages)Console.WriteLine(item.Culture.Name+" "+item.Handle.ToInt64().ToString("X"));return;}SetProcessDpiAwarenessContext(new IntPtr(-4));var form=new ProbeForm{Text="Controller Companion — isolated input test",Width=600,Height=300,StartPosition=FormStartPosition.CenterScreen};var box=new ProbeBox{Multiline=true,AcceptsReturn=true,Dock=DockStyle.Fill,Font=new System.Drawing.Font("Segoe UI",20)};form.Controls.Add(box);
 // Only the isolated fixture activates itself; production never forces foreground focus.
 Action focus=()=>{uint self=GetCurrentThreadId(),fg=GetWindowThreadProcessId(GetForegroundWindow(),IntPtr.Zero);bool attached=self!=fg&&AttachThreadInput(self,fg,true);try{form.TopMost=true;form.Show();form.BringToFront();form.Activate();SetForegroundWindow(form.Handle);box.Focus();Cursor.Position=box.PointToScreen(new System.Drawing.Point(100,100));}finally{if(attached)AttachThreadInput(self,fg,false);}};
 form.Shown+=(s,e)=>{focus();Console.WriteLine("READY:"+form.Handle.ToInt64());Console.Out.Flush();};
 var reader=new Thread(()=>{string line;while((line=Console.ReadLine())!=null){string command=line;try{form.BeginInvoke((Action)(()=>{if(command=="focus")focus();if(command=="hiragana"){box.Focus();Tap(0x16);}if(command=="clear"){box.Clear();box.compositions=0;}if(command.StartsWith("language:")){if(Control.IsKeyLocked(Keys.CapsLock))Tap(0x14);string lang=command.Substring(9),profileResult="error:language-not-installed";foreach(InputLanguage item in InputLanguage.InstalledInputLanguages){if(item.Culture.Name==lang){profileResult=(lang.StartsWith("ja")||lang.StartsWith("zh"))?TsfDefaultProfile.Activate(item):"ok";InputLanguage.CurrentInputLanguage=item;form.BeginInvoke((Action)(()=>{box.Focus();box.ImeMode=lang.StartsWith("ja")?ImeMode.Hiragana:lang.StartsWith("zh")?ImeMode.On:ImeMode.Off;if(lang.StartsWith("ja")){IntPtr context=ImmGetContext(box.Handle);if(context!=IntPtr.Zero){bool opened=ImmSetOpenStatus(context,true);bool converted=ImmSetConversionStatus(context,0x09,0);Console.WriteLine("JOPEN:"+opened+":"+converted+":"+ImmGetOpenStatus(context));ImmReleaseContext(box.Handle,context);}}Console.WriteLine("PROFILE:"+lang+":"+profileResult);Console.WriteLine("LANGUAGE:"+InputLanguage.CurrentInputLanguage.Culture.Name);Console.Out.Flush();}));break;}}}if(command.StartsWith("activate:")){IntPtr wanted=new IntPtr(long.Parse(command.Substring(9)));uint self=GetCurrentThreadId(),fg=GetWindowThreadProcessId(GetForegroundWindow(),IntPtr.Zero);bool attached=self!=fg&&AttachThreadInput(self,fg,true);try{SetForegroundWindow(wanted);}finally{if(attached)AttachThreadInput(self,fg,false);}}if(command=="yield"){form.TopMost=false;form.Hide();Console.WriteLine("YIELDED");Console.Out.Flush();}if(command.StartsWith("cursor:")){form.TopMost=false;string[] xy=command.Substring(7).Split(',');Cursor.Position=new System.Drawing.Point(int.Parse(xy[0]),int.Parse(xy[1]));}if(command=="read"){Console.WriteLine("LANGUAGE:"+InputLanguage.CurrentInputLanguage.Culture.Name);Console.WriteLine("COMPOSITIONS:"+box.compositions);Console.WriteLine("MOUSEONTARGET:"+(WindowFromPoint(Cursor.Position)==box.Handle));Console.WriteLine("VERTICAL:"+ProbeBox.vertical);Console.WriteLine("MEDIA:"+ProbeForm.media);Console.WriteLine("CTRL:"+(GetAsyncKeyState(0x11)<0));Console.WriteLine("SHIFT:"+(GetAsyncKeyState(0x10)<0));Console.WriteLine("MOUSE:"+Cursor.Position.X+","+Cursor.Position.Y+","+ProbeBox.horizontal+","+box.middleDown+","+box.middleUp+","+(GetAsyncKeyState(4)<0?1:0));IntPtr readContext=ImmGetContext(box.Handle);uint conversion=0,sentence=0;bool open=readContext!=IntPtr.Zero&&ImmGetOpenStatus(readContext);if(readContext!=IntPtr.Zero)ImmGetConversionStatus(readContext,out conversion,out sentence);if(readContext!=IntPtr.Zero)ImmReleaseContext(box.Handle,readContext);Console.WriteLine("CAPS:"+Control.IsKeyLocked(Keys.CapsLock));Console.WriteLine("IMEMODE:"+box.ImeMode);Console.WriteLine("IMEOPEN:"+open+":"+conversion);Console.WriteLine("TEXT:"+Convert.ToBase64String(System.Text.Encoding.UTF8.GetBytes(box.Text)));Console.Out.Flush();}if(command=="close")form.Close();}));}catch{break;}}});reader.IsBackground=true;reader.Start();Application.Run(form);
 }
